const leads = $('Read Leads Tab').all().map(i => i.json);
const rejected = $('Read Rejected Tab').all().map(i => i.json);

const now = new Date();
const weekAgo = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);

const inWindow = (row) => {
  const t = row.Timestamp || row.timestamp;
  if (!t) return false;
  const d = new Date(t);
  return !isNaN(d.getTime()) && d >= weekAgo && d <= now;
};

const recentLeads = leads.filter(inWindow);
const recentRejected = rejected.filter(inWindow);

const validLeads = recentLeads.length;
const totalRejected = recentRejected.length;

const breakdown = (rows, key) => {
  const counts = {};
  for (const r of rows) {
    const v = (r[key] ?? '').toString().trim() || 'Unknown';
    counts[v] = (counts[v] || 0) + 1;
  }
  const entries = Object.entries(counts).sort((a, b) => b[1] - a[1]);
  return entries.length ? entries.map(([k, n]) => '  - ' + k + ': ' + n).join('\n') : '  - none';
};

const scores = recentLeads.map(r => parseFloat(r.Score)).filter(n => !isNaN(n));
const avgScore = scores.length ? (scores.reduce((a, b) => a + b, 0) / scores.length).toFixed(1) : 'n/a';

const approvalOf = (r) => (r.Approval ?? '').toString().trim();
const hotLeads = recentLeads.filter(r => approvalOf(r) === 'Hot lead - alerted').length;
const approved = recentLeads.filter(r => approvalOf(r) === 'Approved').length;
const notApproved = recentLeads.filter(r => approvalOf(r) === 'Rejected').length;

const fmt = (d) => d.toLocaleDateString('en-GB', { day: 'numeric', month: 'short', year: 'numeric' });
const range = fmt(weekAgo) + ' - ' + fmt(now);

const report = [
  'Weekly leads report: ' + range,
  '',
  'Valid new leads: ' + validLeads,
  'Rejected as invalid: ' + totalRejected,
  'Hot leads alerted: ' + hotLeads,
  'Follow-up drafts approved: ' + approved,
  'Follow-up drafts rejected: ' + notApproved,
  'Average score: ' + avgScore,
  '',
  'Breakdown by segment (valid leads only):',
  breakdown(recentLeads, 'Segment'),
  '',
  'Breakdown by intent (valid leads only):',
  breakdown(recentLeads, 'Intent'),
].join('\n');

return [{ json: { report, range } }];
